using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class ImageWorkspaceUiOperations:RefCounted
{
    private readonly ImageDocumentOperations _documents=new();private readonly ImageLayerOperations _layers=new();
    private static Variant Get(Settings data,string key,Variant fallback=default)=>data.TryGetValue(key,out var value)?value:fallback;
    private static Control Canvas(Control workspace)=>workspace.Get("canvas").As<Control>();
    private static Node Group(Control workspace,string title,string icon)=>workspace.Call("_toolbar_group",title,icon).As<Node>();
    private static Button ActionButton(Control workspace,Node parent,string title,Action action,string hint="",string icon="")=>workspace.Call("_button",parent,title,Callable.From(action),hint,icon).As<Button>();
    private static void Action(Control workspace,System.Action change)=>workspace.Call("_action",Callable.From(change));
    private static SpinBox NewNumber(Node parent,double value,double minimum,double maximum,double step,double width)
    {
        var number=new DragNumber();number.MinValue=minimum;number.MaxValue=maximum;number.Step=step;number.Value=value;number.CustomMinimumSize=new Vector2((float)width,0);parent.AddChild(number);return number;
    }
    private static void Preview(SpinBox number,Action<double> callback){number.ValueChanged+=value=>callback(value);number.Connect("preview_changed",Callable.From(callback));}
    private static void Picker(Control workspace,Node parent,string name,string title,GArray ids,GArray captions,string current,Action<int> change)=>GD.Load<GDScript>("res://Workspaces/ImageWorkspace/image_warp_picker.gd").Call("build",workspace,parent,name,title,ids,captions,current,Callable.From(change));
    public void warp_build(Control workspace)
    {
        var canvas=Canvas(workspace);var tool=canvas.Get("warp_tool").AsGodotObject();var item=workspace.Call("_main_layer").As<Resource>();if(item!=null&&item.Get("kind").AsString()=="group"){ActionButton(workspace,workspace.Get("context").As<Node>(),"Rasterize group for warp",()=>workspace.Call("rasterize_selected"),"Convert the group to pixels with undo/redo","layers");return;}var modes=Group(workspace,"WARP MODE","warp");var modeIds=new GArray{"brush","mesh","pins"};Picker(workspace,modes,"WarpMode","WARP MODE",modeIds,new GArray{"Warp brush","Mesh warp","Pin warp"},tool.Get("mode").AsString(),index=>{tool.Call("finish");tool.Set("mode",modeIds[index]);if(index==1)tool.Set("show_grid",true);workspace.Call("_refresh_context");workspace.Get("status").As<Label>().Text=workspace.Call("_tool_hint").AsString();canvas.QueueRedraw();});string mode=tool.Get("mode").AsString();
        if(mode=="brush"){var ids=new GArray{"push","pinch","bulge","twirl_cw","twirl_ccw","smooth","restore","freeze","thaw"};Picker(workspace,modes,"WarpBrushType","WARP BRUSH",ids,new GArray{"Push","Pinch","Bulge","Twirl clockwise","Twirl counterclockwise","Smooth geometry","Restore geometry","Freeze areas","Erase freeze"},tool.Get("brush").AsString(),index=>{tool.Call("finish");tool.Set("brush",ids[index]);workspace.Call("_refresh_context");});var size=NewNumber(Group(workspace,"SIZE","brush"),tool.Get("diameter").AsDouble(),2,2048,1,86);size.Suffix="px";Preview(size,value=>{tool.Set("diameter",value);canvas.QueueRedraw();});WarpSlider(workspace,"STRENGTH",tool.Get("strength").AsDouble(),value=>tool.Set("strength",value));WarpSlider(workspace,"FALLOFF",tool.Get("hardness").AsDouble(),value=>tool.Set("hardness",value));var pressure=new CheckButton{Text="Pressure",ButtonPressed=tool.Get("pressure_enabled").AsBool()};modes.AddChild(pressure);pressure.Toggled+=value=>tool.Set("pressure_enabled",value);}
        else if(mode=="mesh"){var influence=Group(workspace,"MESH INFLUENCE","warp");foreach(var entry in new[]{("Radius","mesh_radius",0.0,2.0),("Attenuation","mesh_attenuation",.1,8.0)}){string key=entry.Item2;var label=new Label{Text=entry.Item1};label.AddThemeFontSizeOverride("font_size",11);influence.AddChild(label);var number=NewNumber(influence,tool.Get(key).AsDouble(),entry.Item3,entry.Item4,.01,70);number.TooltipText=key=="mesh_radius"?"Shift+wheel changes radius · Radius 0 moves only selected points":"Higher attenuation reduces the movement of distant points";Preview(number,value=>{tool.Set(key,value);canvas.QueueRedraw();});}var resolution=new OptionButton();modes.AddChild(resolution);int[] sizes={4,8,16};foreach(int size in sizes)resolution.AddItem(size+" × "+size);var warp=item?.Get("warp").AsGodotObject();int current=warp!=null?warp.Get("mesh_resolution").AsInt32():tool.Get("mesh_resolution").AsInt32();resolution.Select(Array.IndexOf(sizes,current));resolution.ItemSelected+=index=>{tool.Set("mesh_resolution",sizes[(int)index]);tool.Set("selected_points",Array.Empty<int>());if(item!=null)Action(workspace,()=>tool.Call("ensure_data",item).AsGodotObject().Call("change_resolution",tool.Get("mesh_resolution")));};ActionButton(workspace,modes,"Reset points",()=>{if(item==null)return;Action(workspace,()=>{var data=tool.Call("ensure_data",item).AsGodotObject();var points=data.Get("mesh_points").AsVector2Array();int size=data.Get("mesh_resolution").AsInt32();foreach(int index in tool.Get("selected_points").AsInt32Array())if(index<points.Length)points[index]=new Vector2(index%size,index/size)/(size-1);data.Set("mesh_points",points);data.Call("touch");});},"Reset selected mesh points","reset");ActionButton(workspace,modes,"Reset mesh",()=>{if(item!=null)Action(workspace,()=>{var data=tool.Call("ensure_data",item).AsGodotObject();data.Call("reset_mesh",data.Get("mesh_resolution"));});},"Reset all mesh points","warp");}
        else if(mode=="pins"){var warp=item?.Get("warp").AsGodotObject();int pinIndex=tool.Get("selected_pin").AsInt32();var pins=warp?.Get("pins").AsGodotArray();var selected=pins!=null&&pinIndex>=0&&pinIndex<pins.Count?pins[pinIndex].AsGodotDictionary():new Settings();var radius=NewNumber(modes,Get(selected,"radius",tool.Get("pin_radius")).AsDouble(),.01,2,.01,80);radius.TooltipText="Influence radius in layer units (1 = layer width)";radius.ValueChanged+=value=>{tool.Set("pin_radius",value);if(selected.Count>0)Action(workspace,()=>{selected["radius"]=value;item!.Get("warp").AsGodotObject().Call("touch");});};var locked=new CheckButton{Text="Lock pin",ButtonPressed=Get(selected,"locked",false).AsBool(),Disabled=selected.Count==0};modes.AddChild(locked);locked.Toggled+=value=>Action(workspace,()=>{selected["locked"]=value;item!.Get("warp").AsGodotObject().Call("touch");});ActionButton(workspace,modes,"Reset pin",()=>{if(selected.Count>0)Action(workspace,()=>{selected["target"]=selected["source"];item!.Get("warp").AsGodotObject().Call("touch");});},"Reset the selected pin","reset");ActionButton(workspace,modes,"Reset pins",()=>{var data=item?.Get("warp").AsGodotObject();if(data!=null)Action(workspace,()=>{foreach(var raw in data.Get("pins").AsGodotArray()){var pin=raw.AsGodotDictionary();pin["target"]=pin["source"];}data.Call("touch");});},"Reset all pin displacements","warp");}
        var options=Group(workspace,"CONSTRAINTS","mask");foreach(var entry in new[]{("Selection only","selection_only"),("Show grid","show_grid"),("Freeze overlay","show_freeze")}){string key=entry.Item2;var check=new CheckButton{Text=entry.Item1,ButtonPressed=tool.Get(key).AsBool()};options.AddChild(check);check.Toggled+=value=>{tool.Set(key,value);canvas.QueueRedraw();};}var actions=Group(workspace,"GEOMETRY","warp");ActionButton(workspace,actions,"Reset warp",()=>{var data=item?.Get("warp").AsGodotObject();if(data!=null)Action(workspace,()=>data.Call("reset_all"));},"Reset all brush, mesh and pin deformation","reset");ActionButton(workspace,actions,"Clear freeze",()=>{var data=item?.Get("warp").AsGodotObject();if(data!=null)Action(workspace,()=>{data.Set("freeze",new float[data.Get("freeze").AsFloat32Array().Length]);data.Call("touch");});},"Clear the freeze mask","eraser");ActionButton(workspace,actions,"Bake",()=>warp_bake(workspace),"Bake deformation to a raster layer","check");ActionButton(workspace,actions,"Cancel",()=>tool.Call("cancel"),"Cancel the current gesture · Esc","close");var enabled=new CheckButton{Text="Enabled",ButtonPressed=item==null||item.Get("warp").AsGodotObject()==null||item.Get("warp").AsGodotObject().Get("enabled").AsBool()};actions.AddChild(enabled);enabled.Toggled+=value=>{if(item!=null)Action(workspace,()=>{tool.Call("ensure_data",item).AsGodotObject().Set("enabled",value);item.Get("warp").AsGodotObject().Call("touch");});};
    }
    private void WarpSlider(Control workspace,string caption,double value,Action<double> setter)
    {
        warp_setting_slider(workspace,caption,value,Callable.From(setter));
    }
    public void warp_setting_slider(Control workspace,string caption,double value,Variant setter)
    {
        var group=Group(workspace,caption,"hardness");group.GetParent().GetChild<TextureRect>(0).Texture=GD.Load<GDScript>("res://Workspaces/ImageWorkspace/image_warp_picker.gd").Call("icon",caption.ToLowerInvariant()).As<Texture2D>();var label=new Label{Text=caption.Capitalize()};label.AddThemeFontSizeOverride("font_size",11);group.AddChild(label);var slider=new HSlider{MinValue=0,MaxValue=1,Step=.01,Value=value,CustomMinimumSize=new Vector2(80,28),TooltipText=caption.Capitalize()};group.AddChild(slider);var percent=new Label{Text=((int)(value*100))+"%",CustomMinimumSize=new Vector2(35,0)};group.AddChild(percent);var bridge=GD.Load<GDScript>("res://Workspaces/ImageWorkspace/image_warp_toolbar.gd");slider.ValueChanged+=next=>{percent.Text=((int)(next*100))+"%";bridge.Call("_set_slider",setter,next);};
    }
    public void warp_bake(Control workspace)
    {
        Canvas(workspace).Get("warp_tool").AsGodotObject().Call("finish");var item=workspace.Call("_main_layer").As<Resource>();if(item==null||item.Get("warp").AsGodotObject()==null)return;var bridge=GD.Load<GDScript>("res://Workspaces/ImageWorkspace/image_warp_toolbar.gd");string id=item.Get("id").AsString();if(item.Get("kind").AsString() is not "image" and not "basic" and not "paint"){var dialog=new ConfirmationDialog{Title="Rasterize and bake warp?",DialogText="This turns the selected layer into editable pixels. Undo can restore its original structure."};workspace.AddChild(dialog);dialog.Confirmed+=()=>{dialog.QueueFree();bridge.Call("_bake_confirmed",workspace,id);};dialog.Canceled+=dialog.QueueFree;dialog.PopupCentered(new Vector2I(430,160));}else bridge.Call("_bake_confirmed",workspace,id);
    }
}
